float getPlotVarScaling(long varMax, long varMin, float displayMax, float displayMin) {
  long varRange = varMax - varMin;
  if (varRange == 0) { varRange = 1; } // prevent divide by zero
  return (displayMax - displayMin)/((float)varRange);
}

void pfodMainMenu::sendMainMenu(pfodParser& parser) {
  // !! Remember to change the parser version string OR Clear the cache
  //    every time you edit this method
  parser.menu();  // start a Menu screen pfod message.  Send {,
  // send menu background, format, prompt, refresh and version
  parser.print(F("<bg n><+4><b>~Arduino Data")); // background n, +4 size, bold
  parser.sendRefreshAndVersion(refresh_ms); // send the menu version 
  // send menu items
  parser.onOffDisplay(datadisplay_A0_Cmd); // start Data Display (outputs |!cmd)
  parser.print(F("<bg n>")); // background n
  parser.print('`');
  parser.print(datadisplay_A0_var); // output the current value
  parser.print(F("~A0 ~V`1023`0~5.0~0~"));
  parser.label(label__Cmd_2); // start Label
  parser.print(F("<bg n><-6>")); // background n, -6 size
  parser.print(F("~"));
  parser.onOffDisplay(onoffdisplay_Door_is_Cmd); // start On/Off Display (outputs |!cmd)
  parser.print(F("<bg n><+4><b>")); // background n, +4 size, bold
  parser.print('`');
  parser.print(onoffdisplay_Door_is_var); // output the current state 0 Closed or 1 Open
  parser.print(F("~Door is ~~Closed\\Open~t"));
  // Note the \\\\ inside the ' 's to send \\ ...
  parser.label(label__Cmd); // start Label
  parser.print(F("<bg n><-6>")); // background n, -6 size
  parser.print(F("~"));
  parser.slider(pwm_PWM_Setting_Cmd); // start Slider
  parser.print(F("<bg n>")); // background n
  parser.print('`');
  parser.print(pwm_PWM_Setting_var); // output the current value 
  parser.print(F("~PWM Setting ~%`255`0~100~0~"));
  parser.slider(onoff_LED_is_Cmd); // start Slider
  parser.print(F("<bg s><+6><b>")); // background silver, +6 size, bold
  parser.print('`');
  parser.print(onoff_LED_is_var); // output the current value 
  parser.print(F("~LED is ~~Off\\On~t"));
  // Note the \\\\ inside the ' 's to send \\ ...
  parser.button(chart_Voltage_Plot_Cmd); // start Button (opens chart)
  parser.print(F("<bg n><+4>")); // background n, +4 size
  parser.print(F("~Voltage Plot"));
  parser.button(submenu_Submenu_Cmd); // start Button (opens sub-menu)
  parser.print(F("<bg n>")); // background n
  parser.print(F("~Submenu"));
  parser.endOfMsg();  // close pfod message. Send }
}

