void datadisplay_A0_Cmd_readADC() {
  if (datadisplay_A0_Cmd_adcTimer.justFinished()) {
    datadisplay_A0_Cmd_adcTimer.repeat(); // restart timer, without drift
    datadisplay_A0_var = analogRead(datadisplay_A0_Cmd_pin);  // read ADC input
  }
}

static void onoff_LED_is_Cmd_checkPulse() {
  if (onoff_LED_is_Cmd_pulseRunning && ((millis() - onoff_LED_is_Cmd_pulseStartTime) > onoff_LED_is_Cmd_PULSE_LENGTH)) {
    onoff_LED_is_Cmd_pulseRunning = false; // timer finished
    onoff_LED_is_var = 0;  // return output to LOW
    digitalWrite(onoff_LED_is_Cmd_pin,onoff_LED_is_var); // update output pin
  }
}

